import type { AstroCookies } from 'astro'
import { createHmac, timingSafeEqual } from 'crypto'

export const PREVIEW_TOKEN_COOKIE_NAME = 'preview-token'

/**
 * Validates a compact HMAC-signed preview token generated by the CMS.
 * Token format: expiry.signature
 */
export function validatePreviewToken(token: string | undefined, secret: string): boolean {
  // Fail closed: an empty secret would allow anyone to sign valid tokens
  if (!secret) {
    throw new Error('PREVIEW_SECRET is not configured')
  }

  if (!token) {
    return false
  }

  const [expStr, sig] = token.split('.')
  if (!expStr || !sig) {
    return false
  }

  // Check expiry (exp is in seconds)
  const exp = parseInt(expStr, 10)
  if (isNaN(exp) || Date.now() / 1000 > exp) {
    return false
  }

  // Generate expected signature using the same method as the CMS
  const expectedSig = createHmac('sha256', secret).update(expStr).digest('base64url').slice(0, 16)

  // Use timing-safe comparison to prevent timing attacks
  if (sig.length !== expectedSig.length) {
    return false
  }
  return timingSafeEqual(Buffer.from(sig), Buffer.from(expectedSig))
}

/**
 * Returns the remaining lifetime of a preview token in seconds.
 */
export function previewTokenMaxAge(token: string): number {
  const exp = parseInt(token.split('.')[0] ?? '', 10)
  return isNaN(exp) ? 0 : Math.max(0, exp - Math.floor(Date.now() / 1000))
}

/**
 * Stores a validated preview token in an HTTP-only cookie scoped to the preview routes.
 * The cookie expires together with the token.
 */
export function setPreviewTokenCookie(cookies: AstroCookies, token: string, secure: boolean) {
  cookies.set(PREVIEW_TOKEN_COOKIE_NAME, token, {
    path: '/preview',
    httpOnly: true,
    secure,
    sameSite: 'lax',
    maxAge: previewTokenMaxAge(token),
  })
}
